from scipy.optimize import least_squares
import itertools
e=df['eps'].values; t=df['T'].values; s=df['sigma'].values
def mk(p1,q1,p2,q2,k,h,k2):
    return np.c_[np.ones_like(e), e**p1*t**q1, e**p2*t**q2, np.exp(-k*e), np.exp(-h/t), np.exp(-k2*e)]
def res(nl,p1,q1,p2,q2):
    X=mk(p1,q1,p2,q2,*nl); c=np.linalg.lstsq(X,s,rcond=None)[0]; return X@c-s
out=[]
for p1,q1,p2,q2 in itertools.product([0.5,0.25,1.0],[2.0,1.5,2.5],[1.0,1.25,1.5,2.0],[1.5,1.75,2.0,1.25]):
    best=None
    for x0 in [[2,3,2],[1,2,1],[3,4,3]]:
        try:
            r=least_squares(res,x0,args=(p1,q1,p2,q2),max_nfev=100)
            v=np.mean(r.fun**2)/np.var(s)
            if best is None or v<best[0]: best=(v,r.x)
        except Exception: pass
    out.append((best[0],p1,q1,p2,q2,np.round(best[1],3)))
out.sort(key=lambda z:z[0])
for o in out[:6]: print(o)
